class BookmarkDBAdapterV1 : BookmarkDBAdapter {

	static readonly int VERSION = 1;

	static readonly int V1_ADDRESS_COL = 0;
	static readonly int V1_TYPE_ID_COL = 1;
	static readonly int V1_TYPE_CATEGORY_COL = 2; // mangled column to improve indexing
	static readonly int V1_COMMENT_COL = 3;

