	private class BatchRecordIterator : RecordIterator {
		private ListIterator<DBRecord> iter;

		BatchRecordIterator(int typeId, long start, long end)
    {
			List<DBRecord> list = new List<DBRecord>();
			Field sf = new LongField(start);
			Field ef = new LongField(end);
			RecordIterator recIter = table.indexIterator(V1_ADDRESS_COL, sf, ef, true);
			while (recIter.hasNext()) {
				list.add(convertV1Record(recIter.next()));
			}
			iter = list.listIterator();
		}

		/* @Override */
		public bool hasNext()
    {
			return iter.hasNext();
		}

		/* @Override */
		public bool hasPrevious()
    {
			return iter.hasPrevious();
		}

		/* @Override */
		public DBRecord next()
    {
			return iter.next();
		}

		/* @Override */
		public DBRecord previous()
    {
			return iter.previous();
		}

		/* @Override */
		public bool delete()
    {
			throw new UnsupportedOperationException();
		}
	}

	private static class V1ConvertedRecordIterator : ConvertedRecordIterator {

